require( "luaunit" )
require( "luaunit_extensions" )
require( "luaunitmockkernel" )

dofile( "../message-box-functions.lua" )

TestMesssageBoxFunctions = {}

function TestMesssageBoxFunctions:setUp()
 	kernel = newluaunitmockkernel()
end

function TestMesssageBoxFunctions:tearDown()
 	kernel = nil
end

function TestMesssageBoxFunctions:test_001_show_nil_message_text_turned_to_empty()
 	kernel:createactor_data( { actor_name = "messagebox_background", add_to_front = false, x = 0, y = 0, width = 1024, height = 768, text = nil, font = nil, image = nil, background_color = "black", foreground_color = nil, text_region = nil, text_translation_point = nil, text_rotation_angle = nil, hotspot = nil, render_options = "Background", hit_options = "Obstruction" } )
 	kernel:setactoropacity_data( { actor_name = "messagebox_background", opacity = .50 } )
	kernel:createactor_data( { actor_name = "messagebox_frame", add_to_front = false, x = 0, y = 0, width = 1024, height = 768, text = nil, font = nil, image = nil, background_color = "white", foreground_color = nil, text_region = nil, text_translation_point = nil, text_rotation_angle = nil, hotspot = nil, render_options = "Background, DrawBorder, DrawRoundedCorners", hit_options = "Enabled" } )
 	kernel:setcornersize_data( { actor_name = "messagebox_frame", width = 5, height = 5 } )
	kernel:createactor_data( { actor_name = "messagebox_text_field", add_to_front = false, x = 0, y = 0, width = 300, height = 90, text = "", font = "medium_font", image = nil, background_color = "white", foreground_color = "black", text_region = nil, text_translation_point = nil, text_rotation_angle = nil, hotspot = nil, render_options = "Text, Background", hit_options = "Obstruction" } )
	kernel:setactortextalignx_data( { actor_name = "messagebox_text_field", alignment = "center" } )
	kernel:setactortextaligny_data( { actor_name = "messagebox_text_field", alignment = "center" } )
	kernel:measureactortext_data( { actor_name = "messagebox_text_field", response = { characters_fitted = 0 } } )
	kernel:createactor_data( { actor_name = "messagebox_icon_field", add_to_front = false, x = 960, y = 0, width = 64, height = 64, text = nil, font = nil, image = "messagebox_information_icon", background_color = nil, foreground_color = nil, text_region = nil, text_translation_point = nil, text_rotation_angle = nil, hotspot = nil, render_options = "Image", hit_options = "Enabled" } )
	kernel:createactor_data( { actor_name = "messagebox_button_bar_ok", add_to_front = false, x = 0, y = 736, width = 72, height = 32, text = "OK", font = "medium_font", image = nil, background_color = "gray", foreground_color = "black", text_region = nil, text_translation_point = nil, text_rotation_angle = nil, hotspot = nil, render_options = "Text, Background, DrawBorder, DrawRoundedCorners", hit_options = "Enabled" } )
	kernel:registeractorhitnotify_data( { actor_name = "messagebox_button_bar_ok" })
	kernel:setactortextalignx_data( { actor_name = "messagebox_button_bar_ok", alignment = "center" } )
	kernel:setactortextaligny_data( { actor_name = "messagebox_button_bar_ok", alignment = "center" } )
	kernel:setcornersize_data( { actor_name = "messagebox_button_bar_ok", width = 5, height = 5 } )
	kernel:getactorwidth_data( { actor_name = "messagebox_text_field", response = 300 } )
	kernel:getactorheight_data( { actor_name = "messagebox_text_field", response = 90 } )
	kernel:getactorwidth_data( { actor_name = "messagebox_icon_field", response = 64 } )
	kernel:getactorheight_data( { actor_name = "messagebox_icon_field", response = 64 } )
	kernel:getviewframe_data( { response = { x = 0, y = 0, width = 1024, height = 768} } )
	kernel:setactorlocation_data( { actor_name = "messagebox_background", x = 0, y = 0 } )
	kernel:setactorlocation_data( { actor_name = "messagebox_frame", x = 320, y = 313 } )
	kernel:setactordimension_data( { actor_name = "messagebox_frame", width = 374, height = 132 } )
	kernel:setactorlocation_data( { actor_name = "messagebox_text_field", x = 325, y = 318 } )
	kernel:setactorlocation_data( { actor_name = "messagebox_icon_field", x = 620, y = 326 } )
 	kernel:setactorlocation_data( { actor_name = "messagebox_button_bar_ok", x = 471, y = 403 } )
	kernel:removeactor_data( { actor_name = "messagebox_text_field" } )
	kernel:removeactor_data( { actor_name = "messagebox_icon_field" } )
	kernel:removeactor_data( { actor_name = "messagebox_button_bar_ok" } )
	kernel:removeactor_data( { actor_name = "messagebox_button_bar_cancel" } )
	kernel:removeactor_data( { actor_name = "messagebox_button_bar_yes" } )
	kernel:removeactor_data( { actor_name = "messagebox_button_bar_no" } )
	kernel:removeactor_data( { actor_name = "messagebox_frame" } )
	kernel:removeactor_data( { actor_name = "messagebox_background" } )

	local o = newmessageboxmanager()
	o:show()
	o:testing_click( o.ButtonOK )
end

